/** Differential tests for the browser state kernel against the pinned Python
 * reference (`fc60a60`). Expected values in the fixture are generated by
 * `frontend/scripts/parallel-kernel/build-kernel-fixtures.py`; this file only
 * applies the browser implementation and compares. */
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import type { EntityDelta, InitialState, Position, TimelinePoint, WorldState } from '../types';
import { canonicalDigest, canonicalJson } from './canonical';
import {
  advanceTime, applyPoint, buildInitialState, KernelViolation, normalizeEntityDelta,
  normalizeSettlementGroup, normalizeTimelinePoint, pointEntityDeltas, replayWorld, stateDigest,
} from './state';

const fixture = JSON.parse(readFileSync(
  resolve('scripts/parallel-kernel/fixtures/kernel-differential.json'), 'utf8'));

function fixtureWorld(name: 'school' | 'fixture' | 'multi'): WorldState {
  return buildInitialState(structuredClone(fixture.worlds[name]) as InitialState);
}

function point(state: WorldState, deltas: Record<string, EntityDelta>, options: {
  id?: string; sequence?: number; amount?: number; previous?: string;
} = {}): TimelinePoint {
  const sequence = options.sequence ?? 1;
  return {
    worldId: state.worldId,
    id: options.id ?? `p${sequence}`,
    sequence,
    kind: 'normal',
    previousPointId: options.previous ?? (sequence === 1 ? 'root_0' : `p${sequence - 1}`),
    roundId: 'round_f',
    advanceId: 'advance_f',
    trigger: 'player',
    linkedFromPointId: null,
    timeAdvance: { boundary: 'elapsed', duration: { amount: options.amount ?? 1, unit: 'second' } },
    entityDeltas: deltas,
  };
}

function expectRefusal(run: () => unknown, expected: string): void {
  let caught: unknown = null;
  try {
    run();
  } catch (error) {
    caught = error;
  }
  expect(caught).not.toBeNull();
  expect(caught).toBeInstanceOf(KernelViolation);
  const kind = (caught as KernelViolation).kind;
  if (expected === 'schema') {
    expect(['semantic_invalid', 'id_unresolved', 'position_invalid']).toContain(kind);
  } else {
    expect(kind).toBe(expected);
  }
}

describe('time advancement', () => {
  it('matches the Python calendar anchors', () => {
    for (const entry of fixture.time.cases) {
      const result = advanceTime(
        { calendar: 'gregorian', dateTime: entry.from, instantOrdinal: 5 },
        entry.advance,
      );
      expect(result).toEqual({ calendar: 'gregorian', dateTime: entry.expected.dateTime,
        instantOrdinal: entry.expected.ordinal });
    }
  });

  it('keeps zero-duration points on the same instant and increments the ordinal', () => {
    const start = { calendar: 'gregorian' as const, dateTime: '2009-10-17T15:20:00', instantOrdinal: 41 };
    expect(advanceTime(start, { boundary: 'instant', duration: { amount: 0, unit: 'second' } }))
      .toEqual({ ...start, instantOrdinal: 42 });
  });

  it('refuses an impossible calendar date instead of letting Date roll it over', () => {
    const start = { calendar: 'gregorian' as const, dateTime: '2026-02-30T00:00:00', instantOrdinal: 0 };
    expect(() => advanceTime(start, { boundary: 'elapsed', duration: { amount: 1, unit: 'second' } }))
      .toThrow(KernelViolation);
  });
});

describe('merge and apply', () => {
  it('merges T01 groups into the Python point deltas', () => {
    const merged = pointEntityDeltas(fixture.normal.groups, null);
    expect(merged).toEqual(fixture.normal.mergedEntityDeltas);
  });

  it('applies the committed point to the Python state digest', async () => {
    const state = fixtureWorld('school');
    expect(await stateDigest(state)).toBe(fixture.normal.stateDigestBefore);
    const final = applyPoint(state, fixture.normal.point);
    expect(await stateDigest(final)).toBe(fixture.normal.stateDigestAfter);
    expect(final).toEqual(fixture.normal.stateAfter);
  });

  it('replays the same point chain to the same digest', async () => {
    const state = fixtureWorld('school');
    expect(await stateDigest(replayWorld(state, [fixture.normal.point]))).toBe(fixture.normal.stateDigestAfter);
    // The start state is not mutated by replay.
    expect(await stateDigest(state)).toBe(fixture.normal.stateDigestBefore);
  });

  it('reproduces the T01 preview projection and both Python anchors', async () => {
    const state = fixtureWorld('school');
    const merged = pointEntityDeltas(fixture.normal.groups, null);
    expect(merged).toEqual(fixture.preview.mergedEntityDeltas);
    const projection = fixture.preview.pointProjection as TimelinePoint;
    expect(await canonicalDigest(projection)).toBe(fixture.preview.pointProjectionDigest);
    const working = applyPoint(state, projection);
    expect(await stateDigest(working)).toBe(fixture.preview.workingStateDigest);
    expect(working).toEqual(fixture.preview.workingState);
  });

  it('normalizes an omitted optional position into explicit nulls', () => {
    const delta = { entityId: 'person_a', positionSet: { containerId: 'room_a' } };
    expect(normalizeEntityDelta(delta)).toEqual({
      entityId: 'person_a',
      positionSet: { containerId: 'room_a', slotId: null, relativeTo: null },
    });
  });
});

describe('position graph', () => {
  for (const entry of fixture.positions.cases) {
    it(`${entry.name} matches the Python outcome`, async () => {
      const state = buildInitialState(structuredClone(entry.initial) as InitialState);
      if (entry.expected.refused) {
        expectRefusal(() => applyPoint(state, point(state, entry.deltas)), entry.expected.refused);
        return;
      }
      const final = applyPoint(state, point(state, entry.deltas));
      expect(await stateDigest(final)).toBe(entry.expected.stateDigest);
    });
  }

  it('is independent of the delta map order when a relative target moves too', async () => {
    const state = fixtureWorld('multi');
    const digests: string[] = [];
    for (const entry of fixture.positions.jointOrders) {
      digests.push(await stateDigest(applyPoint(state, point(state, entry.deltas))));
    }
    expect(digests).toEqual(fixture.positions.jointOrders.map((entry: { stateDigest: string }) => entry.stateDigest));
    expect(new Set(digests).size).toBe(1);
  });

  it('refuses a relative relation whose target moved away in a later point', () => {
    const state = fixtureWorld('multi');
    const settled = applyPoint(state, point(state, {
      person_a: { entityId: 'person_a', positionSet: {
        containerId: 'room_b', slotId: null,
        relativeTo: { entityId: 'item_a', relation: 'beside' },
      } },
      item_a: { entityId: 'item_a', positionSet: { containerId: 'room_b', slotId: null, relativeTo: null } },
    }));
    expectRefusal(
      () => applyPoint(settled, point(state, {
        item_a: { entityId: 'item_a', positionSet: { containerId: 'room_a', slotId: null, relativeTo: null } },
      }, { id: 'p2', sequence: 2, previous: 'p1' })),
      fixture.positions.dangling.expected.refused,
    );
  });
});


describe('task hierarchy and collapse', () => {
  it('sorts new tasks parent-first and marks added-and-achieved ids', async () => {
    const state = fixtureWorld('fixture');
    const merged = pointEntityDeltas(fixture.tasks.cases[0].groups, null);
    expect(merged).toEqual(fixture.tasks.cases[0].expected.merged);
    expect(await stateDigest(applyPoint(state, point(state, merged))))
      .toBe(fixture.tasks.cases[0].expected.stateDigest);
  });

  it('matches the T03-collapse Python merge', () => {
    expect(pointEntityDeltas(fixture.tasks.collapse.groups, null))
      .toEqual(fixture.tasks.collapse.mergedEntityDeltas);
  });

  for (const entry of fixture.tasks.cases.slice(1)) {
    it(`${entry.name} is refused`, () => {
      expectRefusal(() => pointEntityDeltas(entry.groups, null), entry.expected.refused);
    });
  }

  it('refuses a task delta whose owner is not the delta entity', () => {
    expectRefusal(() => normalizeEntityDelta({
      entityId: 'person_a',
      subtasksAdded: [{ id: 't_x', ownerId: 'person_b', parentTaskId: 'task_a', goal: 'x', status: 'pending' }],
    }), 'semantic_invalid');
  });
});

describe('description changes and supersedes', () => {
  it('replays the pure-removal chain to the Python digest and stored flags', async () => {
    const state = fixtureWorld('fixture');
    const final = replayWorld(state, fixture.supersedes.points);
    expect(await stateDigest(final)).toBe(fixture.supersedes.finalStateDigest);
    expect(final).toEqual(fixture.supersedes.finalState);
    const changes = final.items.item_a.appearanceChanges;
    expect(changes.map((change) => [change.id, change.active, change.sourcePointId, change.sourceSequence]))
      .toEqual([['ch_1', false, 'p1', 1], ['ch_2', true, 'p2', 2]]);
  });

  it('refuses one point superseding a change introduced in the same point', () => {
    expectRefusal(
      () => pointEntityDeltas(fixture.supersedes.samePointGroups, null),
      fixture.supersedes.samePointRefused.refused,
    );
  });

  it('refuses a pure removal without supersedes', () => {
    expectRefusal(
      () => pointEntityDeltas(fixture.supersedes.emptyRemovalGroups, null),
      fixture.supersedes.pureRemovalWithoutSupersedes.refused,
    );
  });

  it('refuses a supersede target that is not active in the current state', () => {
    const state = fixtureWorld('fixture');
    expectRefusal(() => applyPoint(state, point(state, {
      item_a: { entityId: 'item_a', appearanceChanges: [{ id: 'ch_2', text: null, supersedes: ['ch_1'] }] },
    })), fixture.supersedes.unknownSupersede.refused);
  });

  it('normalizes and sorts a change supersedes set', () => {
    const normalized = normalizeEntityDelta({
      entityId: 'item_a',
      appearanceChanges: [{ id: 'ch_2', text: null, supersedes: ['ch_b', 'ch_a'] }],
    });
    expect(normalized.appearanceChanges).toEqual([{ id: 'ch_2', text: null, supersedes: ['ch_a', 'ch_b'] }]);
  });
});

describe('point shape', () => {
  it('refuses a normal point with an instant boundary', () => {
    const state = fixtureWorld('fixture');
    const bad = point(state, {}) as TimelinePoint;
    bad.timeAdvance = { boundary: 'instant', duration: { amount: 0, unit: 'second' } };
    expect(() => normalizeTimelinePoint(bad)).toThrow(KernelViolation);
  });

  it('refuses a delta key that differs from its entityId', () => {
    const state = fixtureWorld('fixture');
    expectRefusal(() => applyPoint(state, point(state, {
      item_a: { entityId: 'person_a', appearanceChanges: [{ id: 'ch_1', text: 'x', supersedes: [] }] },
    })), 'semantic_invalid');
  });

  it('round-trips a fixture point through normalization unchanged', () => {
    expect(canonicalJson(normalizeTimelinePoint(fixture.normal.point)))
      .toBe(canonicalJson(fixture.normal.point));
  });

  it('hashes a normalized group exactly like Python unit_content_hash', async () => {
    // T01 s10 settledUnits[0].contentHash and T03-collapse's staged group.
    expect(await canonicalDigest(normalizeSettlementGroup(fixture.normal.groups[0])))
      .toBe('c7ff254c7e13ad1125d3fe7b3d93ec8cf13930dc4d418e38f3f009773af7f175');
    expect(await canonicalDigest(normalizeSettlementGroup(fixture.tasks.collapse.groups[0])))
      .toBe('074d2623815b8341bd8d450d7b89107371aef465722f9c856250a15ffeb80674');
  });

  it('keeps groups normalized for Python-compatible content hashes', () => {
    const normalized = normalizeSettlementGroup({
      groupId: 'g',
      actorIds: ['person_a'],
      positions: { person_a: { containerId: 'room_a' } as Position },
      appearances: {},
      tasksAchieved: {},
      subtasksAdded: {},
      personalities: {},
      sanities: {},
      taskCoverageIds: ['person_b', 'person_a'],
      personalityCoverageIds: [],
    });
    expect(normalized.positions.person_a).toEqual({ containerId: 'room_a', slotId: null, relativeTo: null });
    expect(normalized.taskCoverageIds).toEqual(['person_a', 'person_b']);
  });
});
